function generate(rand, size) {
  const n = size === 'large' ? 1500 + Math.floor(rand() * 501) : 3 + Math.floor(rand() * 8);
  const top = size === 'large' ? 1000000 : [3, 20, 1000000][Math.floor(rand() * 3)];
  const nums = Array.from({ length: n }, () => 1 + Math.floor(rand() * top));
  const shape = rand();
  if (shape < 0.15) nums.sort((x, y) => x - y);
  else if (shape < 0.3) nums.sort((x, y) => y - x);
  return [nums];
}
